import{_ as t,c as a,o as s,ae as r}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Customer Account (Shop)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/customer-account.md","filePath":"api/workflows/shop/customer-account.md"}'),o={name:"api/workflows/shop/customer-account.md"};function i(d,e,l,h,p,n){return s(),a("div",null,e[0]||(e[0]=[r(`<h1 id="customer-account-shop" tabindex="-1">Customer Account (Shop) <a class="header-anchor" href="#customer-account-shop" aria-label="Permalink to &quot;Customer Account (Shop)&quot;">​</a></h1><p>Everything behind a customer login: profile, addresses, order history and invoices, downloadable products, reviews, wishlist, and compare. Every call here needs both the storefront key <strong>and</strong> the customer Bearer token from login.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A valid storefront key (<a href="/api/setup.html">Setup</a>, <a href="/api/authentication.html">Authentication</a>).</li><li>A logged-in customer — the Bearer is the <code>token</code> field from <a href="/api/rest-api/shop/customers/customer-login.html">login</a> (not <code>apiToken</code>).</li></ul><h2 id="dependency-diagram" tabindex="-1">Dependency diagram <a class="header-anchor" href="#dependency-diagram" aria-label="Permalink to &quot;Dependency diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  key[Storefront key] --&gt; login[POST customer login&lt;br/&gt;Bearer token]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; profile[Profile&lt;br/&gt;get / update]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; addr[Addresses&lt;br/&gt;list / create / update / delete]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; orders[Orders&lt;br/&gt;list / detail / invoices]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; dl[Downloadable products]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; reviews[Customer reviews]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; wish[Wishlist]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; cmp[Compare]</span></span></code></pre></div><h2 id="ordered-call-table" tabindex="-1">Ordered call table <a class="header-anchor" href="#ordered-call-table" aria-label="Permalink to &quot;Ordered call table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Endpoint</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td>Login</td><td><a href="/api/rest-api/shop/customers/customer-login.html">POST login</a> · <a href="/api/graphql-api/shop/customer/">GraphQL</a></td><td>Returns the customer Bearer <code>token</code></td></tr><tr><td>2</td><td>Get / update profile</td><td><a href="/api/rest-api/shop/customers/get-customer-profile.html">GET profile</a> · <a href="/api/rest-api/shop/customers/update-customer-profile.html">update</a> · <a href="/api/graphql-api/shop/customer/">GraphQL</a></td><td>Change password via <a href="/api/rest-api/shop/customers/change-password.html">change-password</a></td></tr><tr><td>3</td><td>Manage addresses</td><td><a href="/api/rest-api/shop/customers/get-customer-addresses.html">list</a> · <a href="/api/rest-api/shop/customers/create-customer-address.html">create</a> · <a href="/api/rest-api/shop/customers/update-customer-address.html">update</a> · <a href="/api/rest-api/shop/customers/delete-customer-address.html">delete</a></td><td>Reused at checkout</td></tr><tr><td>4</td><td>Order history</td><td><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">list orders</a> · <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">order detail</a></td><td><code>?status=</code> filters the list</td></tr><tr><td>5</td><td>Invoices</td><td><a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">list</a> · <a href="/api/rest-api/shop/customer-invoices/get-customer-invoice.html">invoice</a> · <a href="/api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.html">PDF</a></td><td>PDF is a binary download</td></tr><tr><td>6</td><td>Downloadable products</td><td><a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-products.html">list</a> · <a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-product.html">item</a></td><td>Purchased downloadable links</td></tr><tr><td>7</td><td>Reviews</td><td><a href="/api/rest-api/shop/customer-reviews/get-customer-reviews.html">list</a> · <a href="/api/rest-api/shop/customer-reviews/get-customer-review.html">review</a> · <a href="/api/graphql-api/shop/product-review/">GraphQL</a></td><td>The customer&#39;s own reviews</td></tr><tr><td>8</td><td>Wishlist</td><td><a href="/api/rest-api/shop/wishlist/list.html">list</a> · <a href="/api/rest-api/shop/wishlist/toggle.html">toggle</a> · <a href="/api/rest-api/shop/wishlist/move-to-cart.html">move to cart</a> · <a href="/api/graphql-api/shop/wishlist/">GraphQL</a></td><td>Channel-scoped</td></tr><tr><td>9</td><td>Compare</td><td><a href="/api/rest-api/shop/compare/list.html">list</a> · <a href="/api/rest-api/shop/compare/create.html">create</a> · <a href="/api/rest-api/shop/compare/delete.html">delete</a> · <a href="/api/graphql-api/shop/compare/">GraphQL</a></td><td>Not channel-scoped</td></tr></tbody></table><blockquote><p><strong>GraphQL equivalents:</strong> <code>readCustomerProfile</code>, <code>customerOrders</code>, <code>wishlists</code> / <code>toggleWishlist</code>, <code>compareItems</code>, <code>productReviews</code>, plus the address mutations.</p></blockquote><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>These are all independent branches off login — call only the ones your screen needs.</li><li>Every step is owner-scoped: a customer only ever sees their own data. Another customer&#39;s id returns <code>403</code>/<code>404</code> (see <a href="/api/errors.html">Errors</a>).</li><li>Returns (RMA), EU Withdrawal, and GDPR are their own flows — see the pages below.</li></ul><h2 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h2><p>To change account behavior on the server, see <a href="/api/workflows/customization/">Customization → Shop</a>.</p>`,13)]))}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
